{"cards": [{"node_code": "N_b7fd3089facf6018", "definition": "研究温度场不随时间变化的导热问题，涵盖一维典型几何、多维稳态分析及热阻网络模型，用于计算稳态热流与温度分布。", "boundary": "聚焦于稳态条件下的导热机理与工程计算。包括平壁、圆筒、球壳等一维解析解，多维导热中的形状因子法及数值解法，以及由多层材料、接触界面和扩展表面构成的热阻网络。与“非稳态导热”的区别在于本节点假设温度场恒定，不涉及热容和瞬态响应；与“多维、各向异性与微尺度导热”的区别在于本节点主要处理宏观尺度、各向同性或简单各向异性介质的稳态问题，不深入微观非傅里叶效应。", "includes": ["一维平壁、圆筒、球壳的稳态导热解析解", "多维稳态导热的形状因子法及有限元/差分数值解法", "复合壁、接触热阻及翅片等扩展表面的热阻网络分析"], "excludes": ["温度场随时间变化的瞬态导热问题（归入非稳态导热与相变导热）", "涉及微尺度效应或非傅里叶热传导的微观导热机理（归入多维、各向异性与微尺度导热）"], "sibling_distinctions": [{"other_code": "N_47371d7d58301cbe", "rule": "本节点研究温度场不随时间变化的稳态问题；兄弟节点研究温度场随时间变化的瞬态及相变过程。"}, {"other_code": "N_a8bf45dec7f9e0a5", "rule": "本节点侧重宏观尺度下的稳态导热计算与热阻模型；兄弟节点侧重复杂几何、各向异性材料特性及微尺度物理效应。"}], "cross_boundary_rule": "若问题涉及稳态但材料具有显著各向异性或处于微尺度，主挂载至“多维、各向异性与微尺度导热”；若为常规宏观稳态问题，主挂载至本节点。"}, {"node_code": "N_47371d7d58301cbe", "definition": "研究温度场随时间变化的导热规律，涵盖瞬态导热解析与数值解法，以及伴随相变潜热释放或吸收的导热过程。", "boundary": "聚焦于非稳态（瞬态）导热及相变导热。包括集总参数法、半无限大物体瞬态导热、多维瞬态数值解，以及熔化、凝固、沸腾等相变过程中的热传导与界面移动问题。与“稳态导热”的区别在于本节点考虑热容效应和温度随时间的演化；与“多维、各向异性与微尺度导热”的区别在于本节点主要关注时间维度的动态变化及相变物理，而非空间维度的复杂几何或微观尺度效应。", "includes": ["集总参数法、半无限大及有限物体瞬态导热分析", "多维非稳态导热的数值模拟方法", "相变导热（如熔化、凝固、潜热存储）及移动边界问题"], "excludes": ["温度场不随时间变化的稳态导热问题（归入稳态导热与热阻网络）", "不涉及相变或瞬态效应的微观尺度导热机理（归入多维、各向异性与微尺度导热）"], "sibling_distinctions": [{"other_code": "N_b7fd3089facf6018", "rule": "本节点研究温度场随时间变化的瞬态及相变过程；兄弟节点研究温度场恒定的稳态问题。"}, {"other_code": "N_a8bf45dec7f9e0a5", "rule": "本节点侧重时间维度的动态演化及相变潜热影响；兄弟节点侧重空间维度的复杂几何、各向异性及微尺度效应。"}], "cross_boundary_rule": "若瞬态问题主要源于微尺度非傅里叶效应，主挂载至“多维、各向异性与微尺度导热”；若为宏观尺度的瞬态或相变过程，主挂载至本节点。"}, {"node_code": "N_a8bf45dec7f9e0a5", "definition": "研究复杂几何形状、各向异性材料特性及微尺度效应下的导热机理，涵盖非傅里叶热传导、声子/电子输运及纳米材料导热。", "boundary": "聚焦于空间维度复杂、材料属性各向异性或尺度进入微观领域的导热问题。包括复杂几何下的导热分析、各向异性热导率张量处理、微纳尺度下的非傅里叶效应（如双相延迟模型）、声子/电子输运机制及纳米复合材料导热。与“稳态导热”的区别在于本节点关注材料微观结构或几何复杂性对导热的影响，而非简单的宏观稳态计算；与“非稳态导热”的区别在于本节点侧重空间/尺度/材料属性的复杂性，而非时间演化。", "includes": ["各向异性材料（如复合材料、晶体）的导热分析", "微尺度及纳米尺度下的非傅里叶热传导与输运机理", "复杂几何形状下的导热问题及纳米材料导热特性"], "excludes": ["常规宏观尺度、各向同性材料的稳态或瞬态导热计算（归入稳态或非稳态导热节点）", "不涉及微观机理的常规工程热阻网络分析（归入稳态导热与热阻网络）"], "sibling_distinctions": [{"other_code": "N_b7fd3089facf6018", "rule": "本节点侧重材料各向异性、微尺度效应及复杂几何；兄弟节点侧重宏观尺度下的稳态热阻与解析/数值解。"}, {"other_code": "N_47371d7d58301cbe", "rule": "本节点侧重空间/尺度/材料属性的复杂性；兄弟节点侧重时间维度的瞬态演化及相变过程。"}], "cross_boundary_rule": "若问题同时涉及瞬态和微尺度效应，需根据主要研究重点判断：若侧重时间演化规律，主挂载至“非稳态导热”；若侧重微观机理或非傅里叶效应，主挂载至本节点。"}]}
